            // Sorted by length (longest first) to avoid partial replacement issues
            const I18N_SORTED = Object.keys(I18N_DICT).sort((a, b) => b.length - a.length);

            let currentLang = localStorage.getItem('preferred_lang') || 'zh-CN';
            let _i18nObserver = null;
            let _translating = false;
            const _origTextMap = new WeakMap();
            const _origAttrMap = new WeakMap();

            function _shouldSkipNode(node) {
                if (!node || node.nodeType !== 3) return true;
                const p = node.parentElement;
                if (!p) return true;
                const tag = p.tagName;
                if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'CODE' || tag === 'PRE') return true;
                // Skip user-generated chat content
                if (p.closest('.msg-text, .msg-bubble, .chat-messages, .chat-messages *')) return true;
                if (p.closest('.memory-content, .scan-result, .kb-content, .feedback-text')) return true;
                if (p.closest('.codehilite, .highlight, pre code')) return true;
                if (p.isContentEditable) return true;
                return false;
            }

            function _translateText(text) {
                if (!text || !/[\u4e00-\u9fff]/.test(text)) return text;
                let result = text;
                for (const zh of I18N_SORTED) {
                    if (result.includes(zh)) {
                        result = result.split(zh).join(I18N_DICT[zh]);
                    }
                }
                return result;
            }

            function _translateNode(root) {
                if (_translating) return;
                _translating = true;
                try {
                    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
                        acceptNode: (n) => _shouldSkipNode(n) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT
                    });
                    const nodes = [];
                    let node;
                    while ((node = walker.nextNode())) nodes.push(node);
                    nodes.forEach(n => {
                        const translated = _translateText(n.nodeValue);
                        if (translated !== n.nodeValue) {
                            if (!_origTextMap.has(n)) _origTextMap.set(n, n.nodeValue);
                            n.nodeValue = translated;
                        }
                    });
                    // Translate attributes
                    root.querySelectorAll('[placeholder], [title], [value], [data-desc]').forEach(el => {
                        if (el.closest('.msg-text, .chat-messages, .codehilite')) return;
                        let orig = _origAttrMap.get(el);
                        if (!orig) { orig = {}; _origAttrMap.set(el, orig); }
                        if (el.hasAttribute('placeholder')) {
                            const ph = el.getAttribute('placeholder');
                            if (orig.placeholder === undefined) orig.placeholder = ph;
                            const tr = _translateText(ph);
                            if (tr !== ph) el.setAttribute('placeholder', tr);
                        }
                        if (el.hasAttribute('title')) {
                            const t = el.getAttribute('title');
                            if (orig.title === undefined) orig.title = t;
                            const tr = _translateText(t);
                            if (tr !== t) el.setAttribute('title', tr);
                        }
                        if (el.tagName === 'BUTTON' && el.hasAttribute('value')) {
                            const v = el.getAttribute('value');
                            if (orig.value === undefined) orig.value = v;
                            const tr = _translateText(v);
                            if (tr !== v) el.setAttribute('value', tr);
                        }
                        if (el.hasAttribute('data-desc')) {
                            const d = el.getAttribute('data-desc');
                            if (orig.dataDesc === undefined) orig.dataDesc = d;
                            const tr = _translateText(d);
                            if (tr !== d) el.setAttribute('data-desc', tr);
                        }
                    });
                } finally {
                    _translating = false;
                }
            }

            function applyTranslations() {
                if (currentLang !== 'en-US') return;
                _translateNode(document.body);
            }

            // 切回中文时恢复原始文本（不刷新页面）
            function _restoreChinese() {
                _translating = true;
                try {
                    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
                        acceptNode: (n) => _shouldSkipNode(n) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT
                    });
                    const nodes = [];
                    let node;
                    while ((node = walker.nextNode())) nodes.push(node);
                    nodes.forEach(n => {
                        if (_origTextMap.has(n)) {
                            n.nodeValue = _origTextMap.get(n);
                            _origTextMap.delete(n);
                        }
                    });
                    document.querySelectorAll('[placeholder], [title], [value], [data-desc]').forEach(el => {
                        const orig = _origAttrMap.get(el);
                        if (orig) {
                            if (orig.placeholder !== undefined) el.setAttribute('placeholder', orig.placeholder);
                            if (orig.title !== undefined) el.setAttribute('title', orig.title);
                            if (orig.value !== undefined) el.setAttribute('value', orig.value);
                            if (orig.dataDesc !== undefined) el.setAttribute('data-desc', orig.dataDesc);
                            _origAttrMap.delete(el);
                        }
                    });
                } finally {
                    _translating = false;
                }
            }

            function setLanguage(lang) {
                if (currentLang === lang) return;
                currentLang = lang;
                localStorage.setItem('preferred_lang', lang);
                const sw = document.getElementById('lang-switch');
                if (sw) sw.textContent = lang === 'zh-CN' ? '中文' : 'EN';
                document.documentElement.lang = lang === 'zh-CN' ? 'zh-CN' : 'en';
                if (lang === 'en-US') {
                    applyTranslations();
                    // Observe dynamic content
                    if (!_i18nObserver) {
                        _i18nObserver = new MutationObserver((mutations) => {
                            if (_translating) return;
                            let needs = false;
                            for (const m of mutations) {
                                if (m.type === 'childList' && m.addedNodes.length) { needs = true; break; }
                                if (m.type === 'characterData') { needs = true; break; }
                            }
                            if (needs) {
                                clearTimeout(window._i18nTimer);
                                window._i18nTimer = setTimeout(applyTranslations, 100);
                            }
                        });
                        _i18nObserver.observe(document.body, {
                            childList: true, subtree: true, characterData: true
                        });
                    }
                } else {
                    if (_i18nObserver) { _i18nObserver.disconnect(); _i18nObserver = null; }
                    _restoreChinese();
                }
            }

            function t(key, vars) {
                const val = I18N_DICT[key] || key;
                if (vars) return val.replace(/\{(\w+)\}/g, (_, k) => vars[k] !== undefined ? vars[k] : '{' + k + '}');
                return val;
            }

            // 立即应用保存的语言偏好（不等启动动画）
            (function initLang() {
                const saved = localStorage.getItem('preferred_lang');
                if (saved === 'en-US') {
                    currentLang = 'en-US';
                    document.documentElement.lang = 'en';
                    const sw = document.getElementById('lang-switch');
                    if (sw) sw.textContent = 'EN';
                    // 等 DOM 就绪后翻译
                    if (document.readyState === 'loading') {
                        document.addEventListener('DOMContentLoaded', () => setTimeout(applyTranslations, 50));
                    } else {
                        setTimeout(applyTranslations, 50);
                    }
                }
            })();

            // ================================================================
            // 5. Markdown
            // ================================================================
            // 降级处理：如果marked库未加载（CDN失败等），提供简易实现
            if (typeof marked === 'undefined') {
                window.marked = {
                    _options: {},
                    setOptions: function(opts) { this._options = opts || {}; },
                    parse: function(text) {
                        if (!text) return '';
                        // 简易Markdown：转义HTML后换行
                        var escaped = text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
                        return '<p>' + escaped.replace(/\n/g,'<br>') + '</p>';
                    }
                };
            }
            // ========== 自研 Markdown 渲染器（无第三方依赖）==========
            // ========== 自研代码高亮器（无第三方依赖）==========
            (function(){
                const LANGS = {
                    python: {
                        keywords: /\b(def|class|return|if|elif|else|for|while|break|continue|try|except|finally|with|as|import|from|lambda|yield|global|nonlocal|assert|pass|raise|del|in|is|not|and|or|True|False|None|self|cls)\b/g,
                        strings: /("""[\s\S]*?"""|'''[\s\S]*?'''|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')/g,
                        comments: /(#[^\n]*)/g,
                        numbers: /\b(\d+\.?\d*[eE]?[+-]?\d*)\b/g,
                        decorators: /(@\w+)/g,
                        builtins: /\b(print|len|range|str|int|float|list|dict|set|tuple|bool|type|isinstance|issubclass|hasattr|getattr|setattr|open|input|enumerate|zip|map|filter|sorted|reversed|sum|min|max|abs|round|pow|hex|oct|bin|chr|ord|repr|eval|exec|compile|__init__|__name__|__main__)\b/g
                    },
                    javascript: {
                        keywords: /\b(const|let|var|function|return|if|else|for|while|do|break|continue|switch|case|default|try|catch|finally|throw|new|class|extends|super|this|import|export|from|default|async|await|yield|typeof|instanceof|in|of|delete|void|true|false|null|undefined|NaN|Infinity)\b/g,
                        strings: /(`[\s\S]*?`|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')/g,
                        comments: /(\/\/[^\n]*|\/\*[\s\S]*?\*\/)/g,
                        numbers: /\b(\d+\.?\d*[eE]?[+-]?\d*)\b/g,
                        regex: /(\/(?:\\.|[^\/\\])+\/[gimsuy]*)/g,
                        builtins: /\b(console|document|window|global|process|require|module|exports|Promise|Array|Object|String|Number|Boolean|Function|Date|Math|JSON|RegExp|Error|Map|Set|WeakMap|WeakSet|Symbol|Proxy|Reflect|fetch|setTimeout|setInterval|clearTimeout|clearInterval)\b/g
                    },
                    c: {
                        keywords: /\b(int|char|float|double|void|short|long|signed|unsigned|const|volatile|static|extern|register|auto|struct|union|enum|typedef|return|if|else|for|while|do|break|continue|switch|case|default|goto|sizeof|inline|restrict|_Bool|_Complex|_Imaginary|true|false|NULL)\b/g,
                        strings: /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')/g,
                        comments: /(\/\/[^\n]*|\/\*[\s\S]*?\*\/)/g,
                        numbers: /\b(0x[0-9a-fA-F]+|\d+\.?\d*[eE]?[+-]?\d*[fFlL]?)\b/g,
                        preprocessor: /(#[^\n]*)/g,
                        builtins: /\b(printf|scanf|malloc|free|calloc|realloc|memcpy|memset|memmove|strcmp|strcpy|strlen|strcat|fopen|fclose|fread|fwrite|fprintf|fscanf|sprintf|sscanf|exit|abort|assert|errno|stdout|stdin|stderr)\b/g
                    },
                    shell: {
                        keywords: /\b(if|then|else|elif|fi|for|while|do|done|case|esac|function|return|break|continue|exit|export|local|readonly|declare|typeset|source|\.|eval|exec|shift|set|unset|trap|cd|echo|printf|read|test|\[\[|\]\])\b/g,
                        strings: /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')/g,
                        comments: /(#[^\n]*)/g,
                        variables: /(\$\{?[\w@#?$!*\-]+\}?)/g,
                        numbers: /\b(\d+)\b/g
                    },
                    json: {
                        strings: /("(?:\\.|[^"\\])*")/g,
                        numbers: /\b(-?\d+\.?\d*[eE]?[+-]?\d*)\b/g,
                        keywords: /\b(true|false|null)\b/g
                    },
                    html: {
                        tags: /(<\/?[a-zA-Z][a-zA-Z0-9]*)/g,
                        attributes: /(\s[a-zA-Z-]+=)/g,
                        strings: /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')/g,
                        comments: /(<!--[\s\S]*?-->)/g
                    },
                    css: {
                        selectors: /([^{}]+\{)/g,
                        properties: /([a-zA-Z-]+)(?=\s*:)/g,
                        strings: /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*')/g,
                        comments: /(\/\*[\s\S]*?\*\/)/g,
                        numbers: /\b(\d+\.?\d*(?:px|em|rem|%|vh|vw|pt|pc|in|cm|mm|ex|ch|vmin|vmax|deg|rad|turn|s|ms|Hz|kHz|dpi|dpcm|dppx)?)\b/g,
                        keywords: /\b(!important|@media|@keyframes|@font-face|@import|@charset|@supports|@page)\b/g
                    },
                    sql: {
                        keywords: /\b(SELECT|FROM|WHERE|INSERT|INTO|VALUES|UPDATE|SET|DELETE|CREATE|TABLE|INDEX|VIEW|DATABASE|ALTER|DROP|TRUNCATE|JOIN|INNER|LEFT|RIGHT|OUTER|FULL|ON|AS|AND|OR|NOT|IN|EXISTS|BETWEEN|LIKE|IS|NULL|ORDER|BY|ASC|DESC|GROUP|HAVING|LIMIT|OFFSET|UNION|ALL|DISTINCT|CASE|WHEN|THEN|ELSE|END|PRIMARY|KEY|FOREIGN|REFERENCES|UNIQUE|CHECK|DEFAULT|AUTO_INCREMENT|CONSTRAINT|CASCADE|RESTRICT|BEGIN|COMMIT|ROLLBACK|TRANSACTION|GRANT|REVOKE|USE|SHOW|DESCRIBE|EXPLAIN)\b/gi,
                        strings: /('(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*")/g,
                        comments: /(--[^\n]*|\/\*[\s\S]*?\*\/)/g,
                        numbers: /\b(\d+\.?\d*)\b/g
                    }
                };
                LANGS.py = LANGS.python;
                LANGS.js = LANGS.javascript;
                LANGS.ts = LANGS.javascript;
                LANGS.jsx = LANGS.javascript;
                LANGS.tsx = LANGS.javascript;
                LANGS.cpp = LANGS.c;
                LANGS['c++'] = LANGS.c;
                LANGS.h = LANGS.c;
                LANGS.hpp = LANGS.c;
                LANGS.bash = LANGS.shell;
                LANGS.sh = LANGS.shell;
                LANGS.zsh = LANGS.shell;
                LANGS.xml = LANGS.html;
                LANGS.svg = LANGS.html;
                LANGS.scss = LANGS.css;
                LANGS.less = LANGS.css;
                LANGS.plain = null;
                LANGS.text = null;
                LANGS.txt = null;
                LANGS[''] = null;

                function escapeHtml(s){
                    return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
                }

                function highlight(code, lang){
                    if(!code) return '';
                    const def = LANGS[lang ? lang.toLowerCase() : ''];
                    if(!def) return escapeHtml(code);
                    let result = escapeHtml(code);
                    // 按优先级替换：注释 > 字符串 > 关键字 > 数字 > 其他
                    const tokens = [];
                    function addToken(regex, cls){
                        result = result.replace(regex, function(m){
                            const idx = tokens.length;
                            tokens.push('<span class="hljs-' + cls + '">' + m + '</span>');
                            return '\x00TOK' + idx + '\x00';
                        });
                    }
                    if(def.comments) addToken(def.comments, 'comment');
                    if(def.strings) addToken(def.strings, 'string');
                    if(def.preprocessor) addToken(def.preprocessor, 'meta');
                    if(def.decorators) addToken(def.decorators, 'meta');
                    if(def.keywords) addToken(def.keywords, 'keyword');
                    if(def.builtins) addToken(def.builtins, 'built_in');
                    if(def.variables) addToken(def.variables, 'variable');
                    if(def.regex) addToken(def.regex, 'regexp');
                    if(def.numbers) addToken(def.numbers, 'number');
                    if(def.tags) addToken(def.tags, 'tag');
                    if(def.attributes) addToken(def.attributes, 'attr');
                    if(def.selectors) addToken(def.selectors, 'selector-tag');
                    if(def.properties) addToken(def.properties, 'attribute');
                    // 恢复token
                    result = result.replace(/\x00TOK(\d+)\x00/g, function(m, idx){
                        return tokens[parseInt(idx)];
                    });
                    return result;
                }

                window.hljs = {
                    getLanguage: function(lang){ return LANGS[lang ? lang.toLowerCase() : ''] ? {name:lang} : null; },
                    highlight: function(code, lang){ return { value: highlight(code, lang && lang.language ? lang.language : null) }; },
                    highlightAuto: function(code){
                        // 简单自动检测：找最匹配的语言
                        let best = 'plain', bestScore = 0;
                        for(const name in LANGS){
                            const def = LANGS[name];
                            if(!def || !def.keywords) continue;
                            const matches = code.match(def.keywords);
                            if(matches && matches.length > bestScore){
                                bestScore = matches.length;
                                best = name;
                            }
                        }
                        return { value: highlight(code, best), language: best };
                    },
                    highlightElement: function(el){
                        if(!el) return;
                        const code = el.textContent || '';
                        const langMatch = el.className.match(/language-([^\s"]+)/);
                        const lang = langMatch ? langMatch[1] : null;
                        el.innerHTML = highlight(code, lang);
                    }
                };
            })();

            // ========== 自研高性能Markdown渲染器（无第三方依赖）==========
            // ========== 代码块围栏解析（渲染器与「复制/保存代码」按钮共用同一实现）==========
            // 支持：3 个及以上反引号或波浪号围栏、任意 info string（c++ / objective-c / py title=x）、
            // 围栏与 info string 之间有空格、更长围栏内的短围栏、闭合围栏位于文本末尾、
            // 未闭合围栏（流式输出）退化为代码块而不再泄漏裸反引号。调用方需先把行尾归一为 LF。
            function parseFencedBlocks(src, makeToken) {
                const text = String(src == null ? '' : src);
                const lines = text.split('\n');
                const blocks = [];
                const out = [];
                let i = 0;
                while (i < lines.length) {
                    // 允许任意缩进（列表项内的围栏是模型常见输出形态），按围栏缩进对内容整体去缩进
                    const open = /^([ \t]*)(`{3,}|~{3,})[ \t]*(.*)$/.exec(lines[i]);
                    // 反引号围栏的 info string 里不允许再出现反引号（否则按普通文本处理）
                    if (open && !(open[2].charAt(0) === '`' && open[3].indexOf('`') !== -1)) {
                        const indent = open[1];
                        const marker = open[2];
                        const info = open[3].trim();
                        let closeIdx = -1;
                        for (let j = i + 1; j < lines.length; j++) {
                            const close = /^([ \t]*)(`{3,}|~{3,})[ \t]*$/.exec(lines[j]);
                            if (close && close[2].charAt(0) === marker.charAt(0) && close[2].length >= marker.length && close[1].length <= indent.length) {
                                closeIdx = j;
                                break;
                            }
                        }
                        const endIdx = closeIdx === -1 ? lines.length : closeIdx;
                        const bodyLines = lines.slice(i + 1, endIdx).map(function (line) {
                            let k = 0;
                            while (k < indent.length) {
                                const ch = line.charAt(k);
                                if (ch !== ' ' && ch !== '\t') break;
                                k++;
                            }
                            return line.slice(k);
                        });
                        blocks.push({
                            // lang 只保留安全字符，避免污染 class 属性
                            lang: (info.split(/\s+/)[0] || '').replace(/[^A-Za-z0-9_+.#\-]/g, ''),
                            // 围栏内一行都没有 → 空内容；否则按行拼接并补上行尾换行
                            code: endIdx > i + 1 ? bodyLines.join('\n') + '\n' : ''
                        });
                        out.push(makeToken ? makeToken(blocks.length - 1) : '');
                        i = closeIdx === -1 ? lines.length : closeIdx + 1;
                        continue;
                    }
                    out.push(lines[i]);
                    i++;
                }
                if (!makeToken) return { text: text, blocks: blocks };
                return { text: out.join('\n'), blocks: blocks };
            }

            // ========== 列表渲染（无序 / 有序 / 任务清单，支持一层缩进）==========
            function convertListBlocks(text) {
                const lines = String(text).split('\n');
                function itemOf(line) {
                    let m = /^([ \t]*)([-*+])\s+\[([ xX])\][ \t]+(.*)$/.exec(line);
                    if (m) return { indent: m[1].length, kind: 'task', checked: m[3].toLowerCase() === 'x', text: m[4] };
                    m = /^([ \t]*)([-*+])\s+(.*)$/.exec(line);
                    if (m) return { indent: m[1].length, kind: 'ul', text: m[3] };
                    m = /^([ \t]*)(\d{1,9})\.\s+(.*)$/.exec(line);
                    if (m) return { indent: m[1].length, kind: 'ol', text: m[3] };
                    return null;
                }
                function parseList(start, indent) {
                    const first = itemOf(lines[start]);
                    const ordered = !!first && first.kind === 'ol';
                    const items = [];
                    let taskList = false;
                    let pos = start;
                    while (pos < lines.length) {
                        const it = itemOf(lines[pos]);
                        if (!it || it.indent < indent) break;
                        if (it.indent > indent) {
                            if (!items.length) break;
                            const sub = parseList(pos, it.indent);
                            items[items.length - 1].nested = sub.html;
                            pos = sub.next;
                            continue;
                        }
                        if ((it.kind === 'ol') !== ordered) break;
                        if (it.kind === 'task') taskList = true;
                        items.push({ it: it, nested: '' });
                        pos++;
                    }
                    let html = ordered ? '<ol>' : (taskList ? '<ul class="task-list">' : '<ul>');
                    items.forEach(function (entry) {
                        if (entry.it.kind === 'task') {
                            html += '<li class="task-item"><input type="checkbox" disabled' + (entry.it.checked ? ' checked' : '') + '> ' + entry.it.text + entry.nested + '</li>';
                        } else {
                            html += '<li>' + entry.it.text + entry.nested + '</li>';
                        }
                    });
                    html += ordered ? '</ol>' : '</ul>';
                    return { html: html, next: pos };
                }
                const chunks = [];
                let i = 0;
                while (i < lines.length) {
                    const it = itemOf(lines[i]);
                    if (it) {
                        const parsed = parseList(i, it.indent);
                        chunks.push(parsed.html);
                        i = parsed.next;
                    } else {
                        chunks.push(lines[i]);
                        i++;
                    }
                }
                return chunks.join('\n');
            }

            // ========== 出站 URL 协议白名单（渲染结果直接进 innerHTML）==========
            function sanitizeUrl(raw, allowImage) {
                const value = String(raw == null ? '' : raw).replace(/[\u0000-\u001f\u007f]/g, '').trim();
                if (!value) return '';
                if (/[\s"'`<>]/.test(value)) return '';
                const scheme = /^([a-zA-Z][a-zA-Z0-9+.\-]*):/.exec(value);
                if (!scheme) return value;
                const name = scheme[1].toLowerCase();
                const allowed = allowImage ? ['http', 'https', 'data'] : ['http', 'https', 'mailto', 'tel', 'ftp'];
                if (allowed.indexOf(name) === -1) return '';
                if (name === 'data' && !/^data:image\//i.test(value)) return '';
                return value;
            }

                function attrSafe(s) {
                    return String(s == null ? '' : s)
                        .replace(/&(?![a-zA-Z#][a-zA-Z0-9]*;)/g, '&amp;')
                        .replace(/"/g, '&quot;')
                        .replace(/'/g, '&#39;');
                }

            window.marked = {
                setOptions: function() {},
                parse: function(text) {
                    if (!text) return '';
                    // 行尾归一：CRLF / CR → LF（否则围栏与行级规则识别失败）
                    let html = String(text).replace(/\r\n?/g, '\n');
                    // 占位符携带随机 nonce，用户文本无法伪造
                    const nonce = '\u0000M' + Math.random().toString(36).slice(2, 10) + '\u0000';
                    const slots = [];
                    const slot = function(fragment) { return nonce + 'I' + (slots.push(fragment) - 1) + nonce; };
                    // 1) 保护围栏代码块：内容原样保存，绝不参与后续块级/行内规则
                    const fenced = parseFencedBlocks(html, function(idx) { return nonce + 'B' + idx + nonce; });
                    html = fenced.text;
                    const codeBlocks = fenced.blocks;
                    // 2) 保护行内代码（不跨行；支持双反引号代码跨度）
                    html = html.replace(/(`+)([^\n]*?)\1(?!`)/g, function(m, ticks, content) {
                        if (!content) return m;
                        return slot('<code>' + escapeHtml(content) + '</code>');
                    });
                    // 3) 转义剩余 HTML（含引号，避免属性位置被逃逸）
                    html = html.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
                    // 表格（GFM）
                    html = html.replace(/^\|(.+)\|\n\|[-:| ]+\|\n((?:\|.+\|\n?)*)/gm, function(m, header, body) {
                        const headers = header.split('|').map(function(h){return h.trim();}).filter(function(h){return h!=='';});
                        const rows = body.trim().split('\n').map(function(row){
                            return row.split('|').map(function(c){return c.trim();}).filter(function(c){return c!=='';});
                        });
                        let table = '<table><thead><tr>';
                        headers.forEach(function(h){table += '<th>' + h + '</th>';});
                        table += '</tr></thead><tbody>';
                        rows.forEach(function(row){
                            table += '<tr>';
                            row.forEach(function(c){table += '<td>' + c + '</td>';});
                            table += '</tr>';
                        });
                        table += '</tbody></table>';
                        return table;
                    });
                    // 标题 # ## ###（带ID）
                    html = html.replace(/^######\s+(.+)$/gm, '<h6>$1</h6>');
                    html = html.replace(/^#####\s+(.+)$/gm, '<h5>$1</h5>');
                    html = html.replace(/^####\s+(.+)$/gm, '<h4>$1</h4>');
                    html = html.replace(/^###\s+(.+)$/gm, '<h3>$1</h3>');
                    html = html.replace(/^##\s+(.+)$/gm, '<h2>$1</h2>');
                    html = html.replace(/^#\s+(.+)$/gm, '<h1>$1</h1>');
                    // 水平线 --- *** ___
                    html = html.replace(/^[-*_]{3,}\s*$/gm, '<hr>');
                    // 粗体 **text** 和 __text__
                    html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
                    html = html.replace(/__([^_]+)__/g, '<strong>$1</strong>');
                    // 斜体 *text* 和 _text_
                    html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');
                    html = html.replace(/(^|\s)_([^_]+)_/g, '$1<em>$2</em>');
                    // 删除线 ~~text~~
                    html = html.replace(/~~([^~]+)~~/g, '<del>$1</del>');
                    // 列表（无序 / 有序 / 任务清单，支持一层缩进）
                    html = convertListBlocks(html);
                    // 引用 > （正文里的 > 已在上面转义成 &gt;）
                    html = html.replace(/^(?:&gt;|>)\s+(.+)$/gm, '<blockquote>$1</blockquote>');
                    // 图片 ![alt](url)（必须先于链接处理，否则前导 ! 会残留成普通文本）
                    // 清理模型把多个 URL 塞进一个链接时混入的逗号（原先在代码块保护之前执行）
                    html = html.replace(/\]\((https?:\/\/[^\s\)]+),([^\)]*)\)/g, ']($1$2)');
                    html = html.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, function(m, alt, url) {
                        const safe = sanitizeUrl(url, true);
                        if (!safe) return alt;
                        return slot('<img src="' + attrSafe(safe) + '" alt="' + attrSafe(alt) + '" style="max-width:100%;">');
                    });
                    // 链接 [text](url)
                    html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, function(m, label, url) {
                        const safe = sanitizeUrl(url, false);
                        if (!safe) return label;
                        return slot('<a href="' + attrSafe(safe) + '" target="_blank" rel="noopener noreferrer">' + label + '</a>');
                    });
                    // 自动链接裸 URL（代码块 / 行内代码 / 已生成的链接都已被占位符隔离）
                    html = html.replace(/(^|[\s>&（(;\["'【])(https?:\/\/[^\s<>）】"'，。；！？、]*)/g, function(m, prefix, rawUrl) {
                        const url = rawUrl.replace(/[.,;:!?)\]}'"]+$/, '');
                        if (!/^https?:\/\/[a-zA-Z0-9][-a-zA-Z0-9.]*\.[a-zA-Z]{2,}/.test(url)) return m;
                        const safe = sanitizeUrl(url, false);
                        if (!safe) return m;
                        return prefix + '<a href="' + attrSafe(safe) + '" target="_blank" rel="noopener noreferrer">' + url + '</a>' + rawUrl.slice(url.length);
                    });
                    // 换行
                    html = html.replace(/\n/g, '<br>');
                    // 恢复代码块（换行已处理完毕，代码内容不会再被改写）
                    html = html.replace(new RegExp(nonce + 'B(\\d+)' + nonce, 'g'), function(m, idx) {
                        const cb = codeBlocks[parseInt(idx, 10)];
                        return '<pre><code class="language-' + (cb.lang || 'plain') + '">' + escapeHtml(cb.code) + '</code></pre>';
                    });
                    // 段落（两个换行）
                    html = html.replace(/<br><br>/g, '</p><p>');
                    if (html && !html.startsWith('<p>') && !html.startsWith('<h') && !html.startsWith('<ul') && !html.startsWith('<ol') && !html.startsWith('<pre') && !html.startsWith('<blockquote') && !html.startsWith('<table') && !html.startsWith('<hr')) {
                        html = '<p>' + html + '</p>';
                    }
                    // 恢复行内槽位（代码跨度 / 链接 / 图片）
                    html = html.replace(new RegExp(nonce + 'I(\\d+)' + nonce, 'g'), function(m, idx) {
                        return slots[parseInt(idx, 10)];
                    });
                    return html;
                }
            };

            function renderMarkdown(text) {
                if (!text) return '';
                // 说明：裸 URL 自动链接、URL 尾部标点切分已移入 marked.parse。
                // 原实现发生在代码块保护之前，会把代码块内容与 [text](url) 里的 URL 一起改写，
                // 造成代码被污染、markdown 链接 href 被写坏，故不再在此处处理。
                let html = marked.parse(text);
                // 移除模型可能输出的水平线和删除线
                html = html.replace(/<hr\s*\/?>/gi, '');
                const tempDiv = document.createElement('div');
                tempDiv.innerHTML = html;
                // 所有链接在应用内浏览器打开（打包环境兼容）
                tempDiv.querySelectorAll('a').forEach(a => {
                    a.setAttribute('target', '_blank');
                    a.setAttribute('rel', 'noopener noreferrer');
                    a.addEventListener('click', function(e) {
                        e.preventDefault();
                        const href = this.getAttribute('href');
                        if (href && typeof window.openInBrowser === 'function') {
                            window.openInBrowser(href);
                        } else if (href) {
                            window.open(href, '_blank');
                        }
                    });
                });
                tempDiv.querySelectorAll('pre').forEach((pre) => {
                    if (pre.parentElement && pre.parentElement.classList.contains('code-block-wrapper')) return;
                    if (pre.querySelector('.copy-btn')) return;
                    const block = pre.querySelector('code');
                    if (block) {
                        try { hljs.highlightElement(block); } catch(e) {}
                    }
                    const wrapper = document.createElement('div');
                    wrapper.className = 'code-block-wrapper';
                    wrapper.style.cssText = 'position:relative;margin:12px 0;';
                    pre.parentNode.insertBefore(wrapper, pre);
                    wrapper.appendChild(pre);
                    pre.style.paddingTop = '40px';
                    pre.style.margin = '0';
                    const lang = block ? block.className.match(/language-([^\s"]+)/) : null;
                    const langLabel = (lang && lang[1] !== 'plain') ? lang[1] : '';
                    if (langLabel) {
                        const label = document.createElement('span');
                        label.className = 'code-lang-label';
                        label.textContent = langLabel;
                        label.style.cssText = 'position:absolute;top:8px;left:12px;color:#888;font-size:0.72rem;font-family:monospace;z-index:10;';
                        wrapper.appendChild(label);
                    }
                    const btn = document.createElement('button');
                    btn.className = 'copy-btn';
                    btn.textContent = '📋 复制';
                    btn.type = 'button';
                    wrapper.appendChild(btn);
                });
                return tempDiv.innerHTML;
            }

            function fallbackCopy(text) {
                const textarea = document.createElement('textarea');
                textarea.value = text;
                textarea.setAttribute('readonly', '');
                textarea.style.cssText = 'position:absolute;left:-9999px;top:0;width:1px;height:1px;opacity:0;';
                document.body.appendChild(textarea);
                textarea.select();
                textarea.setSelectionRange(0, textarea.value.length);
                let ok = false;
                try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
                document.body.removeChild(textarea);
                return ok;
            }

            // 通用复制函数（兼容浏览器、PySide6/WebView）
            // 优先级：QWebChannel原生剪贴板 > navigator.clipboard > execCommand > 服务端API
            function nativeCopy(text) {
                return new Promise((resolve) => {
                    // 1. PySide6 QWebChannel 原生剪贴板
                    if (window.__nativeClipboard && window.__nativeClipboard.copyText) {
                        try {
                            const ok = window.__nativeClipboard.copyText(text);
                            if (ok) { resolve(true); return; }
                        } catch(e) {}
                    }
                    // 2. navigator.clipboard API
                    if (navigator.clipboard && navigator.clipboard.writeText) {
                        navigator.clipboard.writeText(text).then(() => resolve(true)).catch(() => {
                            // 3. execCommand 兜底
                            resolve(fallbackCopy(text));
                        });
                        return;
                    }
                    // 3. execCommand 兜底
                    if (fallbackCopy(text)) { resolve(true); return; }
                    // 4. 服务端剪贴板 API（PySide6/WebView 最终兜底）
                    fetch('/api/clipboard/copy', {
                        method: 'POST', headers: {'Content-Type': 'application/json'},
                        body: JSON.stringify({text: text})
                    }).then(r => r.json()).then(d => resolve(!!d.success)).catch(() => resolve(false));
                });
            }

            // 全局事件委托：代码块复制按钮
            document.addEventListener('click', function(e) {
                const btn = e.target.closest('.copy-btn');
                if (!btn) return;
                e.stopPropagation();
                e.preventDefault();
                const wrapper = btn.closest('.code-block-wrapper') || btn.closest('pre');
                if (!wrapper) return;
                const codeEl = wrapper.querySelector('code');
                const codeText = codeEl ? codeEl.textContent : wrapper.textContent;
                const origText = btn.textContent;
                btn.textContent = '⏳ 复制中...';
                nativeCopy(codeText).then(ok => {
                    btn.textContent = ok ? '✅ 已复制' : '❌ 失败';
                    setTimeout(() => { btn.textContent = origText; }, 1500);
                });
            });

            // 通用复制函数（兼容所有环境）
            function copyToClipboard(text, btn) {
                const origText = btn ? btn.textContent : '';
                if (btn) btn.textContent = '⏳ 复制中...';
                nativeCopy(text).then(ok => {
                    if (!btn) return;
                    btn.textContent = ok ? '✅ 已复制' : '❌ 失败';
                    setTimeout(() => { btn.textContent = origText; }, 1500);
                });
            }

            function appendChatMessage(sender, text, extraActions) {
                const div = document.createElement('div');
                div.className = 'history-item';
                const meta = document.createElement('div');
                meta.className = 'meta';
                meta.textContent = (sender === 'user' ? '您' : '花先生') + ' · ' + new Date().toLocaleTimeString();
                div.appendChild(meta);
                const content = document.createElement('div');
                content.className = 'content';
                if (sender === 'purple' && text) content.innerHTML = renderMarkdown(text);
                else content.textContent = text;
                div.appendChild(content);
                if (sender === 'purple') {
                    const actions = document.createElement('div');
                    actions.className = 'actions';
                    const saveBtn = document.createElement('button');
                    saveBtn.textContent = '📝 保存到镜像舱';
                    saveBtn.onclick = function(e) {
                        e.stopPropagation();
                        const topic = prompt('请输入主题（默认 default）：', 'default') || 'default';
                        fetch(API_MIRROR_POST, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ text: text, topic: topic, user_id: userId })
                        }).then(r => r.json()).then(data => {
                            if (data.success) alert('✅ 已保存到镜像舱');
                            else alert('保存失败: ' + (data.error || '未知错误'));
                        }).catch(err => alert('保存失败: ' + err.message));
                    };
                    actions.appendChild(saveBtn);
                    const copyBtn = document.createElement('button');
                    copyBtn.textContent = '📋 复制纯文本';
                    copyBtn.onclick = function(e) {
                        e.stopPropagation();
                        copyToClipboard(text, copyBtn);
                    };
                    actions.appendChild(copyBtn);
                    if (extraActions) {
                        if (Array.isArray(extraActions)) extraActions.forEach(act => actions.appendChild(act));
                        else actions.appendChild(extraActions);
                    }
                    div.appendChild(actions);
                }
                if (chatMessages) { chatMessages.appendChild(div);
                    chatMessages.scrollTop = chatMessages.scrollHeight; }
            }

            let currentThinkingBox = null;
            let currentThinkingText = '';
            let currentStreamingDiv = null;  // 跟踪当前正在流式输出的回复框

            function resetThinkingBox() {
                currentThinkingBox = null;
                currentThinkingText = '';
            }

            function showThinkingBox(thinkingText) {
                if (!chatMessages) return;
                currentThinkingText += thinkingText;
                if (!currentThinkingBox) {
                    currentThinkingBox = document.createElement('div');
                    currentThinkingBox.className = 'thinking-box';
                    currentThinkingBox.innerHTML =
                        '<div class="thinking-header" onclick="window.toggleThinking(this)"><span>💭 思考过程</span><span class="toggle-arrow">▾</span></div><div class="thinking-body"></div>';
                    // 插入到当前流式回复之前；如果还没有回复框，追加到末尾
                    if (currentStreamingDiv && currentStreamingDiv.parentNode) {
                        chatMessages.insertBefore(currentThinkingBox, currentStreamingDiv);
                    } else {
                        chatMessages.appendChild(currentThinkingBox);
                    }
                }
                const body = currentThinkingBox.querySelector('.thinking-body');
                if (body) body.innerHTML = renderMarkdown(currentThinkingText);
                chatMessages.scrollTop = chatMessages.scrollHeight;
            }
            window.toggleThinking = function(header) {
                const body = header.parentElement.querySelector('.thinking-body');
                const arrow = header.querySelector('.toggle-arrow');
                if (body.style.display === 'none') { body.style.display = 'block';
                    arrow.textContent = '▾'; } else { body.style.display = 'none';
                    arrow.textContent = '▸'; }
            };

            // 全局链接点击委托：聊天区域所有链接在内置浏览器打开
            if (chatMessages) {
                chatMessages.addEventListener('click', function(e) {
                    const link = e.target.closest('a');
                    if (!link) return;
                    const href = link.getAttribute('href');
                    if (!href) return;
                    // 只处理http/https链接
                    if (!/^https?:\/\//i.test(href)) return;
                    e.preventDefault();
                    e.stopPropagation();
                    if (typeof window.openInBrowser === 'function') {
                        window.openInBrowser(href);
                    } else {
                        window.open(href, '_blank');
                    }
                });
            }

            // ================================================================
            // 6. 对话
            // ================================================================
            let chatAbortController = null;
            // ==================== 云端视频/图片生成 ====================
            // 刻意不做「聊天里随便一句话就偷偷生成」：只认下面这些显式写法。
            // 触发点在对话流程里，进度和结果都显示在对话原地，不另开窗口。
            const MR_VIDEO_CMD = /^(?:\/video|生成视频|做视频|拍个视频|生成一段视频)\s*[:：]?\s*(.+)$/i;
            const MR_IMAGE_CMD = /^(?:\/image|\/img|生成图片|生成图像|画图|画一张|生成一张图)\s*[:：]?\s*(.+)$/i;

            function mrParseGenCommand(text) {
                const t = String(text || '').trim();
                let m = MR_VIDEO_CMD.exec(t);
                if (m) return { kind: 'video', prompt: m[1].trim() };
                m = MR_IMAGE_CMD.exec(t);
                if (m) return { kind: 'image', prompt: m[1].trim() };
                return null;
            }

            // 查看历史产出：整句都是指令，不带参数。
            // 生成的文件默认落在数据目录的 video/ 与 image/ 下，
            // 由 /api/video/list 汇总；这里取回来内联播放，省得去翻磁盘。
            const MR_GENLIST_CMD = /^(?:\/genlist|\/gen|\/list|生成历史|生成记录|查看生成|我的视频|查看视频|图片历史)\s*$/i;

            function mrIsGenListCommand(text) {
                return MR_GENLIST_CMD.test(String(text || '').trim());
            }

            async function mrRunGenList() {
                const box = mrGenBubble('📂 正在读取生成历史…');
                const setBox = (h) => {
                    if (box) { box.innerHTML = h; chatMessages.scrollTop = chatMessages.scrollHeight; }
                };
                try {
                    const r = await fetch('/api/video/list', { credentials: 'include' });
                    const j = await r.json().catch(() => ({}));
                    if (!r.ok || !j.success) {
                        setBox('⚠️ 读取生成历史失败：' + (j.error || ('HTTP ' + r.status)));
                        return;
                    }
                    const items = asArray(j.items);
                    if (!items.length) {
                        setBox('📂 还没有已生成的产出。<br>'
                             + '<span style="font-size:0.75rem;color:#666;">'
                             + '可用「生成视频：&lt;描述&gt;」发起一次生成。</span>');
                        return;
                    }
                    // 每条的路径交给 mrRichMedia 内联成 <video>/<img>，点开即可播放
                    let body = '';
                    items.forEach(function (it) {
                        const kb = Math.max(1, Math.round((it.size || 0) / 1024));
                        let when = '';
                        try { when = new Date(it.mtime * 1000).toLocaleString(); } catch (e) { when = ''; }
                        body += '\n' + it.path + '\n' + (when ? when + ' · ' : '') + kb + ' KB';
                    });
                    setBox('📂 已生成 ' + items.length + ' 项（最新在前）：' + mrRichMedia(body));
                } catch (e) {
                    setBox('⚠️ 读取生成历史出错：' + e.message);
                }
            }

            function mrGenBubble(html) {
                if (!chatMessages) return null;
                const div = document.createElement('div');
                div.className = 'chat-msg assistant';
                div.style.cssText = 'padding:10px 14px;margin:6px 0;border-radius:10px;background:#f5f7fa;';
                div.innerHTML = html;
                chatMessages.appendChild(div);
                chatMessages.scrollTop = chatMessages.scrollHeight;
                return div;
            }

            // 对话模型自主发起的生成提案。
            //
            // 模型只负责判断「用户要不要生成」和「画面怎么描述」，真正花钱的那一步
            // 始终由这里发起 —— 所以即便模型判断错了，默认设置下也不会产生费用。
            function mrHandleGenProposal(d) {
                if (!d || !d.prompt) return;
                const label = d.kind === 'image' ? '图片' : '视频';
                const box = mrGenBubble('🤖 模型判断你需要生成' + label + '…');
                const reason = d.reason
                    ? '<div style="margin-top:4px;color:#666;">' + escapeHtml(d.reason) + '</div>'
                    : '';
                if (!d.need_confirm) {
                    // 全自动：不打断对话，直接进入已有生成流程
                    if (box) box.innerHTML = '🤖 已自动开始生成' + label + '…';
                    mrRunGeneration(d.kind, d.prompt, true);
                    return;
                }
                // 默认：把实际要用的提示词原样摊开，用户点了才开始花钱
                if (box) {
                    box.innerHTML =
                        '<div style="font-weight:600;">🤖 模型建议生成' + label + '</div>' +
                        reason +
                        '<div style="margin-top:6px;padding:6px 8px;background:#f6f8fa;border-radius:6px;font-size:0.78rem;line-height:1.5;">' +
                        escapeHtml(d.prompt) +
                        '</div>' +
                        '<button class="mr-gen-confirm" style="margin-top:8px;padding:4px 12px;cursor:pointer;border-radius:5px;">开始生成</button>';
                    const btn = box.querySelector('.mr-gen-confirm');
                    if (btn) {
                        btn.addEventListener('click', function () {
                            btn.disabled = true;
                            btn.textContent = '已开始…';
                            mrRunGeneration(d.kind, d.prompt, true);
                        });
                    }
                }
            }

            async function mrRunGeneration(kind, prompt, fromModel) {
                const label = kind === 'video' ? '视频' : '图片';
                const box = mrGenBubble('🎬 准备生成' + label + '…');
                const setBox = (h) => {
                    if (box) { box.innerHTML = h; chatMessages.scrollTop = chatMessages.scrollHeight; }
                };
                try {
                    const sub = await fetch('/api/video/generate', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        credentials: 'include',
                        // fromModel=true 表示提示词已由对话模型针对生成模型写好，
                        // 后端据此跳过二次改写（二次改写会截断，见 web.py 说明）
                        body: JSON.stringify({ kind: kind, prompt: prompt, prompt_from_model: !!fromModel })
                    });
                    const sj = await sub.json().catch(() => ({}));
                    if (!sub.ok || !sj.success) {
                        // 未开启 / 隐私拒绝 / 参数问题 都从这里出来，不做静默处理
                        setBox('⚠️ 无法生成：' + (sj.error || ('HTTP ' + sub.status))
                               + '<div style="font-size:0.72rem;color:#8a6d3b;margin-top:6px;word-break:break-all;">'
                               + '本次提交的提示词：' + escapeHtml(String(prompt))
                               + '</div>');
                        return;
                    }
                    const flag = sj.sanitized
                        ? '<div style="font-size:0.72rem;color:#8a6d3b;margin-top:4px;">🔒 提示词已按隐私规则脱敏后发送</div>'
                        : '';
                    let step = 0;
                    const timer = setInterval(async () => {
                        step++;
                        try {
                            const r = await fetch('/api/video/status/' + encodeURIComponent(sj.task_id), { credentials: 'include' });
                            const j = await r.json().catch(() => ({}));
                            if (!j.success) { clearInterval(timer); setBox('⚠️ 查询任务失败：' + (j.error || r.status)); return; }
                            const task = j.task || {};
                            const pct = Math.round((task.progress || 0) * 100);
                            const msg = task.progress_message || task.status || '';
                            // 后端返回的是枚举的 .value，为**小写**（success / failed / dead_letter）。
                            // 这里必须先统一大小写再比对：直接用大写字面量比较会让下面两个分支
                            // 永远不命中 —— 表现为「生成成功却不出视频、一直停在进度行」，
                            // 以及「失败时不报错，只把 dead_letter 当成进度文字显示」。
                            const st = String(task.status || '').toUpperCase();
                            if (st === 'SUCCESS') {
                                clearInterval(timer);
                                const res = j.result || {};
                                if (res.success && res.path) {
                                    // 若提示词被模型改写过，如实显示实际发送的内容 ——
                                    // 改写是黑箱的话用户没法判断结果为什么和描述不一致。
                                    let usedNote = '';
                                    if (res.prompt_enhanced && res.prompt_used) {
                                        usedNote = '<div style="font-size:0.72rem;color:#555;'
                                                 + 'margin-top:6px;word-break:break-all;">'
                                                 + '✍️ 实际发送的提示词：'
                                                 + escapeHtml(String(res.prompt_used))
                                                 + '</div>';
                                    }
                                    setBox('✅ 生成完成' + flag + usedNote
                                           + mrRichMedia('\n' + res.path));
                                } else {
                                    setBox('⚠️ 生成失败：' + (res.error || '未知原因') + flag);
                                }
                                return;
                            }
                            if (st === 'FAILED' || st === 'DEAD_LETTER' || st === 'CANCELLED') {
                                clearInterval(timer);
                                setBox('⚠️ 生成失败：' + (task.error || '未知原因')
                                       + '<div style="font-size:0.72rem;color:#8a6d3b;margin-top:6px;word-break:break-all;">'
                                       + '本次提交的提示词：' + escapeHtml(String(prompt))
                                       + '</div>');
                                return;
                            }
                            setBox('🎬 正在生成' + label + '… ' + pct + '%' + (msg ? '（' + msg + '）' : '') + flag);
                        } catch (e) {
                            clearInterval(timer);
                            setBox('⚠️ 查询任务出错：' + e.message);
                        }
                    }, 2000);
                } catch (e) {
                    setBox('⚠️ 请求失败：' + e.message);
                }
            }

            async function sendChatStream(message) {
                if (isWaiting) return;
                if (!message || !message.trim()) return;
                const trimmed = message.trim();

                // 显式生成指令：走云端生成，不发给对话模型。
                // 只认明确写法，避免误触发产生费用。
                if (mrIsGenListCommand(trimmed)) {
                    appendChatMessage('user', trimmed);
                    if (chatInput) { chatInput.value = ''; chatInput.style.height = 'auto'; }
                    await mrRunGenList();
                    return;
                }
                const genCmd = mrParseGenCommand(trimmed);
                if (genCmd && genCmd.prompt) {
                    appendChatMessage('user', trimmed);
                    if (chatInput) { chatInput.value = ''; chatInput.style.height = 'auto'; }
                    await mrRunGeneration(genCmd.kind, genCmd.prompt);
                    return;
                }

                appendChatMessage('user', trimmed);
                if (chatInput) { chatInput.value = ''; chatInput.style.height = 'auto'; }
                isWaiting = true;
                resetThinkingBox();
                showLoading();
                showStatus('思考中', 'thinking');
                if (window.OrbHub && window.OrbHub.react) window.OrbHub.react('thinking');
                // 显示停止按钮，隐藏发送按钮
                const sendBtn = document.getElementById('chat-send');
                const stopBtn = document.getElementById('chat-stop');
                if (sendBtn) sendBtn.style.display = 'none';
                if (stopBtn) stopBtn.style.display = 'inline-block';

                let accumulatedText = '';
                let placeholderDiv = null;
                let content = null;
                let replyStarted = false;
                let replyCompleted = false;
                let replyErrored = false;
                let streamRenderTimer = null;
                let lastRenderTime = 0;
                chatAbortController = new AbortController();

                try {
                    const response = await fetch(API_CHAT_STREAM, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ message: trimmed, user_id: userId, context: {}, lang: currentLang }),
                        credentials: 'include',
                        signal: chatAbortController.signal
                    });
                    if (response.status === 401) {
                        throw new Error('登录状态已失效，请重新登录后再发送消息');
                    }
                    if (!response.ok) throw new Error('HTTP ' + response.status);
                    const reader = response.body.getReader();
                    const decoder = new TextDecoder();
                    let buffer = '';
                    while (true) {
                        const { done, value } = await reader.read();
                        if (done) break;
                        buffer += decoder.decode(value, { stream: true });
                        const parts = buffer.split('\n\n');
                        buffer = parts.pop() || '';
                        for (const part of parts) {
                            if (!part.startsWith('data: ')) continue;
                            const jsonStr = part.replace(/^data: /, '').trim();
                            if (!jsonStr) continue;
                            let data;
                            try { data = JSON.parse(jsonStr); } catch (e) { console.warn('解析失败:', jsonStr); continue; }
                            if (replyCompleted) continue;
                            if (data.type === 'thinking') {
                                showThinkingBox(data.content);
                            } else if (data.type === 'tool_status') {
                                // 显示工具执行状态
                                if (!replyStarted) {
                                    placeholderDiv = createPlaceholderMessage();
                                    content = placeholderDiv.querySelector('.content');
                                    replyStarted = true;
                                }
                                // 灵体反应：工具开始执行
                                if (window.OrbHub && window.OrbHub.react) {
                                    window.OrbHub.react('scan');
                                }
                                // 搜索/侦察/抓取完成 → 广播任务动态
                                var _tc = data.content || '';
                                if (typeof broadcastActivity === 'function') {
                                    if (_tc.indexOf('搜索完成') >= 0 || _tc.indexOf('侦察完成') >= 0) {
                                        broadcastActivity('web_search', '', '🔍 信息收集完成', 'info');
                                    } else if (_tc.indexOf('页面抓取完成') >= 0) {
                                        broadcastActivity('web_fetch', '', '🌐 页面抓取完成', 'info');
                                    }
                                }
                                // 心跳消息不重置已接收的内容，只在还没有正文时显示
                                var isHeartbeat = data.content && data.content.indexOf('⏳') >= 0;
                                if (!isHeartbeat && !accumulatedText.trim()) {
                                    if (content) content.innerHTML = '<span style="color:#9b59b6;">' + escapeHtml(data.content || '执行工具中...') + '</span>';
                                } else if (!isHeartbeat) {
                                    // 有正文后收到状态消息，不覆盖正文，只记录不显示
                                } else if (!accumulatedText.trim() && content) {
                                    content.innerHTML = '<span style="color:#9b59b6;">' + escapeHtml(data.content || '执行工具中...') + '</span>';
                                }
                            } else if (data.type === 'tool_progress') {
                                // 工具执行进度条
                                if (!replyStarted) {
                                    placeholderDiv = createPlaceholderMessage();
                                    content = placeholderDiv.querySelector('.content');
                                    replyStarted = true;
                                }
                                // 广播任务动态到镜像舱（无论是否有正文都要记录）
                                handleToolBroadcast(data);
                                // 模型说话后也能显示进度条，不覆盖模型回复
                                // 如果模型已经说了话，在模型回复后面追加一个新的 div 来显示进度条
                                var progressContainer = content;
                                if (accumulatedText.trim()) {
                                    // 模型已经说了话，创建一个新的 div 来显示进度条
                                    var existingProgressDiv = content.querySelector('.tool-progress-append');
                                    if (existingProgressDiv) {
                                        progressContainer = existingProgressDiv;
                                    } else {
                                        var progressDiv = document.createElement('div');
                                        progressDiv.className = 'tool-progress-append';
                                        progressDiv.style.cssText = 'margin-top:8px;padding-top:8px;border-top:1px dashed #e0e0e0;';
                                        content.appendChild(progressDiv);
                                        progressContainer = progressDiv;
                                    }
                                }
                                handleToolProgress(data, progressContainer);
                            } else if (data.type === 'web_view') {
                                // 模型正在查看网页，根据用户设置选择浏览器
                                if (!data.url) return;
                                var btMode = localStorage.getItem('browserTrackMode') || 'internal';
                                if (btMode === 'internal' && typeof window.aiViewPage === 'function') {
                                    window.aiViewPage(data.url);
                                } else if (btMode === 'external') {
                                    window.open(data.url, '_blank');
                                }
                                // off 模式：不打开任何浏览器
                            } else if (data.type === 'gen_proposal') {
                                // 对话模型自主发起的生成请求。
                                // need_confirm=true → 渲染卡片等用户确认；false → 直接开跑。
                                // 两种模式只差这一个分支，提示词/进度/渲染全部复用已有流程。
                                mrHandleGenProposal(data);
                            } else if (data.type === 'clear') {
                                // 服从重试或工具第二轮：只重置工具进度状态，不清空之前的输出
                                // （后端会在 clear 之后立即重新发送之前的可见文本，前端不需要主动清空）
                                if (_toolProgressTimer) { clearInterval(_toolProgressTimer); _toolProgressTimer = null; }
                                _toolProgressState = null;
                            } else if (data.type === 'chunk') {
                                if (!data.content) continue;
                                if (!replyStarted) {
                                    placeholderDiv = createPlaceholderMessage();
                                    content = placeholderDiv.querySelector('.content');
                                    replyStarted = true;
                                    if (window.OrbHub && window.OrbHub.react) window.OrbHub.react('speaking');
                                }
                                accumulatedText += data.content;
                                // 过滤残留的工具标签，防止 innerHTML 把 <<< 当成 HTML 标签擦除
                                accumulatedText = accumulatedText.replace(/<<<[A-Z_]+:[^>]*>>>/g, '').replace(/<<<BATCH>>>/g, '');
                                // 流式渲染：16ms防抖（约60fps），顺滑不卡顿
                                if (content) {
                                    const now = Date.now();
                                    if (now - lastRenderTime >= 16) {
                                        lastRenderTime = now;
                                        if (streamRenderTimer) { clearTimeout(streamRenderTimer); streamRenderTimer = null; }
                                        content.innerHTML = renderMarkdown(accumulatedText);
                                        if (chatMessages) chatMessages.scrollTop = chatMessages.scrollHeight;
                                    } else if (!streamRenderTimer) {
                                        streamRenderTimer = setTimeout(() => {
                                            streamRenderTimer = null;
                                            content.innerHTML = renderMarkdown(accumulatedText);
                                            if (chatMessages) chatMessages.scrollTop = chatMessages.scrollHeight;
                                        }, 16);
                                    }
                                }
                            } else if (data.type === 'done') {
                                replyCompleted = true;
                                if (window.OrbHub) window.OrbHub.setState('');
                                if (streamRenderTimer) { clearTimeout(streamRenderTimer); streamRenderTimer = null; }
                                if (placeholderDiv && content && !replyErrored) {
                                    if (accumulatedText.trim()) {
                                        content.innerHTML = renderMarkdown(accumulatedText);
                                        addActionButtons(placeholderDiv, accumulatedText);
                                    } else { content.textContent = '（对方暂时没有回应）'; }
                                }
                            } else if (data.type === 'error') {
                                replyCompleted = true;
                                replyErrored = true;
                                if (!replyStarted) {
                                    placeholderDiv = createPlaceholderMessage();
                                    content = placeholderDiv.querySelector('.content');
                                    replyStarted = true;
                                }
                                if (content) content.textContent = '⚠️ ' + data.content;
                            } else if (data.type === 'orb_finding') {
                                // 后端检测到安全发现，灵体按严重程度反应
                                try {
                                    if (window.OrbHub && window.OrbHub.finding) {
                                        window.OrbHub.finding(data.severity || 'info', data.message);
                                    }
                                } catch (e) {
                                    console.warn('[orb] finding 失败', e);
                                }
                            } else if (data.type === 'orb_command'
                                       || (data.action && typeof data.action === 'string'
                                           && ['open', 'guide', 'emote', 'state', 'move',
                                               'attract', 'react', 'skin', 'companion'].indexOf(data.action) >= 0)) {
                                // 后端实时下发灵体指令（SSE 即时到达，不等 2 秒轮询）。
                                // 第二个条件兼容历史格式：命令自带的 type 曾经覆盖了信封的
                                // type，事件以 {"type":"finding",...} 到达，命中不到 orb_command。
                                // 另外灵体动作是纯装饰，任何异常都不能冒泡 —— 这里冒泡会被
                                // 外层 catch 当成「连接中断」，把整轮对话直接结束掉。
                                try {
                                    if (window.OrbHub && window.OrbHub.executeCommand && data.action) {
                                        window.OrbHub.executeCommand(data);
                                    }
                                } catch (e) {
                                    console.warn('[orb] 执行指令失败', e);
                                }
                            }
                        }
                    }
                } catch (err) {
                    if (err.name === 'AbortError') {
                        // 用户主动停止
                        replyCompleted = true;
                        if (accumulatedText && placeholderDiv) {
                            if (streamRenderTimer) { clearTimeout(streamRenderTimer); streamRenderTimer = null; }
                            const finalContent = placeholderDiv.querySelector('.content');
                            if (finalContent) {
                                finalContent.innerHTML = renderMarkdown(accumulatedText);
                                addActionButtons(placeholderDiv, accumulatedText);
                            }
                        } else if (placeholderDiv) {
                            const c = placeholderDiv.querySelector('.content');
                            if (c) c.textContent = '⏹ 已停止生成';
                        }
                    } else if (!replyCompleted) {
                        replyCompleted = true;
                        if (!replyStarted) {
                            placeholderDiv = createPlaceholderMessage();
                            content = placeholderDiv.querySelector('.content');
                            replyStarted = true;
                        }
                        if (content) content.textContent = '⚠️ 连接中断: ' + err.message;
                    }
                    // AbortError 是「用户点停止」或「新消息取消了上一轮」的正常路径，
                    // 记成 console.error 会被错误监控当成页面错误上报（每次停止多一条）。
                    if (!err || err.name !== 'AbortError') {
                        console.error(err);
                    } else if (window.console && console.debug) {
                        console.debug('[chat] 已取消本轮生成');
                    }
                } finally {
                    isWaiting = false;
                    hideLoading();
                    showStatus('在线', 'online');
                    // 无论成功/失败/中断，都清除灵体状态
                    if (window.OrbHub) window.OrbHub.setState('');
                    if (window.OrbHub && window.OrbHub.setProgress) window.OrbHub.setProgress(false);
                    chatAbortController = null;
                    if (placeholderDiv) placeholderDiv.classList.remove('streaming-reply');
                    currentStreamingDiv = null;  // 清除当前流式回复引用
                    if (streamRenderTimer) { clearTimeout(streamRenderTimer); streamRenderTimer = null; }
                    // 恢复发送按钮，隐藏停止按钮
                    if (sendBtn) sendBtn.style.display = 'inline-block';
                    if (stopBtn) stopBtn.style.display = 'none';
                    if (!replyCompleted && accumulatedText && placeholderDiv) {
                        const finalContent = placeholderDiv.querySelector('.content');
                        if (finalContent) {
                            finalContent.innerHTML = renderMarkdown(accumulatedText);
                            addActionButtons(placeholderDiv, accumulatedText);
                        }
                    }
                }
            }

            let _toolProgressState = null;
            let _toolProgressTimer = null;

            // 工具事件广播到镜像舱（独立于UI渲染，无论是否有正文都执行）
            let _toolBroadcastState = null;
            function handleToolBroadcast(data) {
                const phase = data.phase;
                if (phase === 'start') {
                    _toolBroadcastState = {
                        tool: data.tool || '',
                        target: data.target || '',
                        isSingle: (data.total || 1) === 1,
                        startTime: Date.now()
                    };
                    if (typeof broadcastPresence === 'function') {
                        broadcastPresence('scanning', data.tool || '', data.target || '');
                    }
                } else if (phase === 'task_done') {
                    if (typeof broadcastActivity === 'function') {
                        broadcastActivity(data.tool || '', data.target || '',
                            (data.success ? '✅' : '❌') + ' ' + (data.tool || '') + ' → ' + (data.target || '') + ' (' + (data.duration || 0) + 's)',
                            data.success ? 'info' : 'warning');
                    }
                    if (_toolBroadcastState) _toolBroadcastState.broadcasted = true;
                } else if (phase === 'complete') {
                    if (typeof broadcastPresence === 'function') {
                        broadcastPresence('idle', '', '');
                    }
                    // 单工具可能没有task_done事件，在complete时补一条（已广播过则跳过）
                    if (_toolBroadcastState && _toolBroadcastState.isSingle && !_toolBroadcastState.broadcasted && typeof broadcastActivity === 'function') {
                        const elapsed = ((Date.now() - _toolBroadcastState.startTime) / 1000).toFixed(1);
                        broadcastActivity(_toolBroadcastState.tool, _toolBroadcastState.target,
                            '✅ ' + _toolBroadcastState.tool + ' → ' + _toolBroadcastState.target + ' (' + elapsed + 's)', 'info');
                    }
                    _toolBroadcastState = null;
                }
            }

            function handleToolProgress(data, container) {
                if (!container) return;
                const phase = data.phase;

                if (phase === 'start') {
                    // 灵体进入扫描状态
                    if (window.OrbHub && window.OrbHub.react) window.OrbHub.react('scan');
                    // 初始化进度条
                    const total = data.total || 1;
                    const isSingle = total === 1;
                    _toolProgressState = {
                        total: total,
                        done: 0,
                        startTime: Date.now(),
                        tasks: [],
                        isSingle: isSingle,
                        tool: data.tool || '',
                        target: data.target || ''
                    };
                    let titleHtml;
                    if (isSingle) {
                        titleHtml = `<span style="color:#9b59b6;">${escapeHtml(data.content || '调用工具中...')}</span>`;
                    } else {
                        titleHtml = `<span style="color:#9b59b6;">${escapeHtml(data.content || '批量执行中...')}</span>`;
                    }
                    container.innerHTML = `
                        <div class="tool-progress-wrap${isSingle ? ' tool-progress-indeterminate' : ''}">
                            <div class="tool-progress-title">${titleHtml}</div>
                            <div class="tool-progress-bar">
                                <div class="tool-progress-fill" style="${isSingle ? 'left:-30%;width:30%' : 'width:0%'}"></div>
                            </div>
                            <div class="tool-progress-info">
                                <span class="tool-progress-count">${isSingle ? '执行中...' : '0/' + total}</span>
                                <span class="tool-progress-elapsed">0s</span>
                            </div>
                            <div class="tool-progress-tasks"></div>
                        </div>
                    `.trim();
                    // 启动计时器
                    if (_toolProgressTimer) clearInterval(_toolProgressTimer);
                    _toolProgressTimer = setInterval(() => {
                        if (!_toolProgressState) return;
                        const elapsed = ((Date.now() - _toolProgressState.startTime) / 1000).toFixed(0);
                        const el = container.querySelector('.tool-progress-elapsed');
                        if (el) el.textContent = elapsed + 's';
                    }, 500);

                } else if (phase === 'task_start') {
                    // 单个任务开始
                    if (!_toolProgressState) return;
                    const tasksEl = container.querySelector('.tool-progress-tasks');
                    if (tasksEl) {
                        const taskEl = document.createElement('div');
                        taskEl.className = 'tool-task-item tool-task-running';
                        taskEl.id = 'tool-task-' + data.tool + '-' + data.target.replace(/[^a-z0-9]/gi, '');
                        taskEl.innerHTML = `<span class="tool-task-icon">⏳</span> ${escapeHtml(data.tool)} → ${escapeHtml(data.target)}`;
                        tasksEl.appendChild(taskEl);
                    }

                } else if (phase === 'task_done') {
                    // 单个任务完成：灵体轻微反应
                    if (data.success && window.OrbHub && window.OrbHub.glow) {
                        window.OrbHub.glow('rgba(46,204,113,0.4)', 600);
                    }
                    // 单个任务完成
                    if (!_toolProgressState) return;
                    _toolProgressState.done = data.done;
                    const pct = Math.round((data.done / data.total) * 100);
                    const fill = container.querySelector('.tool-progress-fill');
                    if (fill) fill.style.width = pct + '%';
                    const count = container.querySelector('.tool-progress-count');
                    if (count) count.textContent = `${data.done}/${data.total}`;
                    // 更新任务状态
                    const taskId = 'tool-task-' + data.tool + '-' + (data.target || '').replace(/[^a-z0-9]/gi, '');
                    const taskEl = container.querySelector('#' + taskId);
                    if (taskEl) {
                        taskEl.className = 'tool-task-item ' + (data.success ? 'tool-task-ok' : 'tool-task-fail');
                        taskEl.innerHTML = `<span class="tool-task-icon">${data.success ? '✅' : '❌'}</span> ${escapeHtml(data.tool)} → ${escapeHtml(data.target)} <span class="tool-task-dur">${escapeHtml(String(data.duration))}s</span>`;
                    } else {
                        // 没有task_start事件，直接添加完成项
                        const tasksEl = container.querySelector('.tool-progress-tasks');
                        if (tasksEl) {
                            const te = document.createElement('div');
                            te.className = 'tool-task-item ' + (data.success ? 'tool-task-ok' : 'tool-task-fail');
                            te.innerHTML = `<span class="tool-task-icon">${data.success ? '✅' : '❌'}</span> ${escapeHtml(data.tool)} → ${escapeHtml(data.target)} <span class="tool-task-dur">${escapeHtml(String(data.duration))}s</span>`;
                            tasksEl.appendChild(te);
                        }
                    }

                } else if (phase === 'heartbeat') {
                    // 心跳：更新进度数字和耗时
                    if (!_toolProgressState) return;
                    const count = container.querySelector('.tool-progress-count');
                    if (count && data.done != null) {
                        count.textContent = _toolProgressState.isSingle
                            ? `执行中... ${data.elapsed || Math.round((Date.now() - _toolProgressState.startTime) / 1000)}s`
                            : `${data.done}/${data.total}`;
                    }
                    const el = container.querySelector('.tool-progress-elapsed');
                    if (el && data.elapsed != null) el.textContent = data.elapsed + 's';

                } else if (phase === 'complete') {
                    // 灵体完成反应
                    if (window.OrbHub && window.OrbHub.react) window.OrbHub.react('complete');
                    // 全部完成
                    if (_toolProgressTimer) { clearInterval(_toolProgressTimer); _toolProgressTimer = null; }
                    if (_toolProgressState) {
                        const elapsed = ((Date.now() - _toolProgressState.startTime) / 1000).toFixed(1);
                        const wrap = container.querySelector('.tool-progress-wrap');
                        if (wrap) wrap.classList.remove('tool-progress-indeterminate');
                        const fill = container.querySelector('.tool-progress-fill');
                        if (fill) { fill.style.animation = 'none'; fill.style.left = '0'; fill.style.width = '100%'; }
                        const count = container.querySelector('.tool-progress-count');
                        if (count) count.textContent = `✓ 完成`;
                        const el = container.querySelector('.tool-progress-elapsed');
                        if (el) el.textContent = elapsed + 's';
                        if (_toolProgressState.isSingle) {
                            // 单工具：显示完成后淡出
                            const titleEl = container.querySelector('.tool-progress-title span');
                            if (titleEl) titleEl.textContent = `✅ 工具执行完成 (${elapsed}s)`;
                        }
                    }
                    _toolProgressState = null;
                    // 1.5秒后清除进度条，让模型回复显示
                    setTimeout(() => {
                        const wrap = container.querySelector('.tool-progress-wrap');
                        if (wrap) wrap.style.transition = 'opacity 0.5s';
                        if (wrap) wrap.style.opacity = '0';
                    }, 1500);
                }
            }

            function createPlaceholderMessage() {
                const div = document.createElement('div');
                div.className = 'history-item streaming-reply';
                const meta = document.createElement('div');
                meta.className = 'meta';
                meta.textContent = (window._currentPersonaName || 'AI') + ' · ' + new Date().toLocaleTimeString();
                div.appendChild(meta);
                const content = document.createElement('div');
                content.className = 'content';
                div.appendChild(content);
                if (chatMessages) {
                    // 如果思考框已存在，插入到思考框后面；否则追加到末尾
                    if (currentThinkingBox && currentThinkingBox.parentNode) {
                        currentThinkingBox.parentNode.insertBefore(div, currentThinkingBox.nextSibling);
                    } else {
                        chatMessages.appendChild(div);
                    }
                    currentStreamingDiv = div;
                    chatMessages.scrollTop = chatMessages.scrollHeight;
                }
                return div;
            }

            function addActionButtons(placeholderDiv, text) {
                const actionsDiv = document.createElement('div');
                actionsDiv.className = 'actions';

                // 提取markdown代码块（与渲染器共用同一套围栏解析，避免两处实现不一致）
                function extractCodeBlocks(src) {
                    const parsed = parseFencedBlocks(String(src == null ? '' : src).replace(/\r\n?/g, '\n'));
                    return parsed.blocks.map(function (b) {
                        return { lang: b.lang || 'text', code: b.code.replace(/\n$/, '') };
                    });
                }

                const codeBlocks = extractCodeBlocks(text);
                if (codeBlocks.length > 0) {
                    // 复制代码按钮
                    const copyCodeBtn = document.createElement('button');
                    copyCodeBtn.textContent = '📋 复制代码';
                    copyCodeBtn.onclick = function(e) {
                        e.stopPropagation();
                        const allCode = codeBlocks.map(b => b.code).join('\n\n');
                        copyToClipboard(allCode, copyCodeBtn);
                    };
                    actionsDiv.appendChild(copyCodeBtn);

                    // 保存代码按钮（只保存代码，不含其他内容）
                    const saveCodeBtn = document.createElement('button');
                    saveCodeBtn.textContent = '💾 保存代码';
                    saveCodeBtn.onclick = function(e) {
                        e.stopPropagation();
                        const extMap = {python:'py',py:'py',javascript:'js',js:'js',jsx:'jsx',typescript:'ts',ts:'ts',html:'html',htm:'html',css:'css',c:'c',cpp:'cpp','c++':'cpp',cs:'cs',csharp:'cs',go:'go',rust:'rs',rs:'rs',bash:'sh',shell:'sh',sh:'sh',sql:'sql',java:'java',kotlin:'kt',swift:'swift',php:'php',ruby:'rb',rb:'rb',json:'json',yaml:'yml',yml:'yml',xml:'xml',markdown:'md',md:'md',text:'txt'};
                        if (codeBlocks.length === 1) {
                            const b = codeBlocks[0];
                            const ext = extMap[b.lang] || 'txt';
                            const defaultName = 'code_' + Date.now() + '.' + ext;
                            const outPath = prompt('保存代码到：', '~/Desktop/' + defaultName);
                            if (!outPath) return;
                            fetch(API_BASE + '/api/file/write', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({ path: outPath, content: b.code })
                            }).then(r => r.json()).then(data => {
                                alert(data.success ? '✅ 代码已保存到: ' + data.path : '❌ 保存失败: ' + (data.error || '未知错误'));
                            }).catch(err => alert('保存失败: ' + err.message));
                        } else {
                            // 多个代码块：分别保存
                            const dir = prompt('多个代码块，保存到目录（如 ~/Desktop/codes/）：', '~/Desktop/codes/');
                            if (!dir) return;
                            Promise.all(codeBlocks.map((b, i) => {
                                const ext = extMap[b.lang] || 'txt';
                                const fname = 'block_' + (i+1) + '_' + Date.now() + '.' + ext;
                                const fpath = dir.replace(/\/?$/, '/') + fname;
                                return fetch(API_BASE + '/api/file/write', {
                                    method: 'POST',
                                    headers: { 'Content-Type': 'application/json' },
                                    body: JSON.stringify({ path: fpath, content: b.code })
                                }).then(r => r.json());
                            })).then(results => {
                                const ok = results.filter(r => r.success).length;
                                alert('✅ 已保存 ' + ok + '/' + codeBlocks.length + ' 个代码文件到 ' + dir);
                            }).catch(err => alert('保存失败: ' + err.message));
                        }
                    };
                    actionsDiv.appendChild(saveCodeBtn);
                }

                // 检测文件写入结果，添加"在编辑器中打开"按钮
                const fileWriteMatch = text.match(/📁 路径: (.+)/);
                if (fileWriteMatch && fileWriteMatch[1]) {
                    const filePath = fileWriteMatch[1].trim();
                    const openEditorBtn = document.createElement('button');
                    openEditorBtn.textContent = '📂 在编辑器中打开';
                    openEditorBtn.onclick = function(e) {
                        e.stopPropagation();
                        if (typeof window.openFileInEditor === 'function') {
                            window.openFileInEditor(filePath);
                        } else {
                            openWindow('codeeditor');
                            alert('请在代码编辑器中手动打开: ' + filePath);
                        }
                    };
                    actionsDiv.appendChild(openEditorBtn);
                }

                const saveBtn = document.createElement('button');
                saveBtn.textContent = '保存到镜像舱';
                saveBtn.onclick = function(e) {
                    e.stopPropagation();
                    const topic = prompt('请输入主题（默认 default）：', 'default') || 'default';
                    fetch(API_MIRROR_POST, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ text: text, topic: topic, user_id: userId })
                    }).then(r => r.json()).then(data => {
                        if (data.success) alert('已保存到镜像舱');
                        else alert('保存失败: ' + (data.error || '未知错误'));
                    }).catch(err => alert('保存失败: ' + err.message));
                };
                actionsDiv.appendChild(saveBtn);

                const saveFileBtn = document.createElement('button');
                saveFileBtn.textContent = '💾 保存到文件';
                saveFileBtn.onclick = function(e) {
                    e.stopPropagation();
                    const defaultName = 'mrhua_reply_' + new Date().toISOString().slice(0,10) + '.txt';
                    const outPath = prompt('保存到本地路径（如 /tmp/ 或 ~/Desktop/）：', '~/Desktop/' + defaultName);
                    if (!outPath) return;
                    fetch(API_BASE + '/api/file/write', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ path: outPath, content: text })
                    }).then(r => r.json()).then(data => {
                        if (data.success) alert('✅ 已保存到: ' + data.path);
                        else alert('保存失败: ' + (data.error || '未知错误'));
                    }).catch(err => alert('保存失败: ' + err.message));
                };
                actionsDiv.appendChild(saveFileBtn);

                const copyBtn = document.createElement('button');
                copyBtn.textContent = '复制纯文本';
                copyBtn.onclick = function(e) {
                    e.stopPropagation();
                    copyToClipboard(text, copyBtn);
                };
                actionsDiv.appendChild(copyBtn);

                const goodBtn = document.createElement('button');
                goodBtn.textContent = '👍';
                goodBtn.title = '满意';
                goodBtn.onclick = function(e) {
                    e.stopPropagation();
                    submitFeedback('回复很好，满意');
                    goodBtn.textContent = '✅';
                    setTimeout(() => goodBtn.textContent = '👍', 1500);
                };
                actionsDiv.appendChild(goodBtn);

                const badBtn = document.createElement('button');
                badBtn.textContent = '👎';
                badBtn.title = '不满意';
                badBtn.onclick = function(e) {
                    e.stopPropagation();
                    const fb = prompt('请告诉我们哪里需要改进：', '');
                    if (fb && fb.trim()) {
                        submitFeedback(fb.trim());
                        badBtn.textContent = '✅';
                        setTimeout(() => badBtn.textContent = '👎', 1500);
                    }
                };
                actionsDiv.appendChild(badBtn);

                placeholderDiv.appendChild(actionsDiv);
            }

            function submitFeedback(content) {
                fetch(API_BASE + '/api/feedback', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ content: content, user_id: userId })
                }).then(r => r.json()).then(data => {
                    if (data.learned) {
                        let msg = '📚 已学习你的反馈';
                        if (data.param_changes && data.param_changes.length) {
                            msg += '\n参数调整: ' + data.param_changes.map(c => c.param + '→' + c.new.toFixed(2)).join(', ');
                        }
                        if (data.prompt_added && data.prompt_added.length) {
                            msg += '\n新增偏好: ' + data.prompt_added.join('; ');
                        }
                        console.log(msg);
                    }
                }).catch(err => console.warn('反馈提交失败:', err));
            }

            // ================================================================
            // 7. 语音输入（MediaRecorder + 后端转写，QtWebEngine 安全）
            // ================================================================
            if (voiceBtn) {
                if (window.VoiceInput && VoiceInput.supported) {
                    voiceBtn.addEventListener('click', function() {
                        if (VoiceInput.isRecording) {
                            voiceBtn.textContent = '⏳';
                            VoiceInput.stop();
                            return;
                        }
                        VoiceInput.start(function(ev) {
                            if (ev.state === 'recording') {
                                voiceBtn.textContent = '🔴';
                                voiceBtn.style.background = '#ff6b6b';
                            } else if (ev.state === 'processing') {
                                voiceBtn.textContent = '⏳';
                            } else if (ev.state === 'result') {
                                if (chatInput) {
                                    chatInput.value = ev.text;
                                    chatInput.focus();
                                }
                                voiceBtn.textContent = '🎤';
                                voiceBtn.style.background = '#6a4c93';
                            } else if (ev.state === 'error') {
                                voiceBtn.textContent = '🎤';
                                voiceBtn.style.background = '#6a4c93';
                                console.warn('语音识别:', ev.error);
                            }
                        });
                    });
                } else {
                    voiceBtn.title = '当前环境不支持语音录制';
                    voiceBtn.style.opacity = '0.4';
                }
            }

