                            div.innerHTML = '<span style="font-size:0.78rem;"><span style="display:inline-block;width:12px;height:12px;border-radius:50%;background:' + (tag.color || '#999') + ';margin-right:6px;vertical-align:middle;"></span>' + ncEscape(tag.name || 'unnamed') + '</span><span style="font-size:0.72rem;color:#999;">' + (tag.asset_count || 0) + ' 个资产</span>';
                            el.appendChild(div);
