                            div.innerHTML = '<div style="font-weight:600;color:#333;">' + ncEscape(scan.scan_type || scan.type || '扫描') + ' - ' + ncEscape(scan.target || '--') + '</div>';
                            div.innerHTML += '<div style="color:#666;margin-top:2px;">发现 ' + (scan.assets_found || 0) + ' 个资产, ' + (scan.open_ports_total || 0) + ' 个开放端口</div>';
